# DK RME.  Rask Mølle - Ejstrupholm
#
let re = path("d3.dk.rme");

with detail = 3, railway = :first :pax :removed {
    # point.dk.Rask-Mølle  dk.HTG

    with link = "line.dk.RME" {
        track(:lor,
                re[:ras.ye - 0.1dl, :ras.ye] >> 1ms >> 1mt
